"""Build results/tuning/MPC_CMA.md: CMA-ES-tuned MPC vs the hand-tuned MPC and the references."""
import json
from pathlib import Path

import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
R = ROOT / "results"


def mean(path):
  f = R / "runs" / path
  return pd.read_csv(f) if f.exists() else None


def main():
  t = json.load(open(R / "tuning" / "mpc_cma.json"))
  timing = json.load(open(R / "timing.json"))
  cfg = t["config"]
  L = ["# CMA-ES tuning of the MPC + observer", "",
       "Generated by `scripts/summarize_mpc_cma.py`. Tuner: `scripts/tune_mpc_cma.py` (popsize 12, "
       f"{len(t['log'])} generations). Objective: dev {t['objective_segs']}; overfitting check: dev {t['check_segs']}.", "",
       "## Chosen parameters (frozen in `controllers/mpc_cma.py`)", "",
       "| parameter | hand-tuned MPC | CMA-ES MPC |", "|---|---|---|",
       f"| tracking weight (jerk weight = 1) | 1 | {cfg['w_track']:.3f} |",
       f"| steer-rate weight | 4 | {cfg['w_du']:.3f} |",
       f"| horizon | 40 | {cfg['H']} |",
       f"| observer q_d | 3e-3 | {cfg['kf']['q_d']:.3g} |",
       f"| observer q_k | 1e-5 | {cfg['kf']['q_k']:.3g} |",
       f"| observer r | 2e-3 | {cfg['kf']['r']:.3g} |",
       f"| speed breakpoints [m/s] | 5, 10, 15, 20, 25, 30, 35 | {', '.join(f'{e:.1f}' for e in cfg['edges'][1:-1])} |", "",
       f"CMA-ES candidate kept: `{t['chosen']}` (the better of best-evaluated and CMA-ES mean on the check set).", "",
       "## Inside the tuner (rollouts by the tuner itself)", "",
       "| candidate | objective set | check set |", "|---|---:|---:|"]
  for k in t["objective_mean_total"]:
    L.append(f"| {k} | {t['objective_mean_total'][k]:.3f} | {t['check_mean_total'][k]:.3f} |")
  L += ["", "## Official runs of the frozen controllers (`scripts/run_eval.py`)", "",
        "| segments | hand-tuned MPC (`mpc`) | CMA-ES MPC (`mpc_cma`) | paired difference (cma - hand) |", "|---|---:|---:|---:|"]
  for rng, label in [("10500-10999", "dev objective set"), ("11000-11499", "dev check set"),
                     ("10000-10499", "dev 500 (standard)"), ("00000-04999", "test 5000 (run once)")]:
    a, b = mean(f"mpc_{rng}.csv"), mean(f"mpc_cma_{rng}.csv")
    if a is None or b is None:
      continue
    d = (b.set_index("seg").total_cost - a.set_index("seg").total_cost).dropna()
    L.append(f"| {label} {rng} | {a.total_cost.mean():.3f} | {b.total_cost.mean():.3f} | "
             f"{d.mean():+.3f} +- {d.std() / np.sqrt(len(d)):.3f} |")
  test = mean("mpc_cma_00000-04999.csv")
  if test is not None:
    ms = timing.get("mpc_cma", {}).get("ms_per_step")
    L += ["", "## Test result next to the references", "",
          "| controller | test total | ms/step | source |", "|---|---:|---:|---|",
          f"| CMA-ES MPC + observer | {test.total_cost.mean():.2f} | {ms:.2f} | this run |" if ms else
          f"| CMA-ES MPC + observer | {test.total_cost.mean():.2f} | | this run |",
          f"| hand-tuned MPC + observer | {mean('mpc_00000-04999.csv').total_cost.mean():.2f} | "
          f"{timing['mpc']['ms_per_step']:.2f} | results/runs |",
          f"| iLQR through TinyPhysics | {mean('ilqr_00000-04999.csv').total_cost.mean():.2f} | "
          f"{timing['ilqr']['ms_per_step']:.1f} | results/runs |",
          f"| PID+FF, CMA-ES (ours) | {mean('pid_ff_cma_00000-04999.csv').total_cost.mean():.2f} | "
          f"{timing['pid_ff_cma']['ms_per_step']:.3f} | results/runs |",
          "| comma blog, CMA-ES-tuned custom feedback controller | 48.0 | | blog.comma.ai/rlcontrols (not reproduced) |",
          "| leaderboard best PID+FF | 50.608 | | comma.ai/leaderboard (not reproduced) |"]
  # learned-residual rule: only if a fast controller (ms/step well under the 100 ms period) is below 48 on test
  fast = {}
  for name in ["pid_ff", "pid_ff_cma", "lqr", "mpc_noobs", "mpc", "mpc_admm", "mpc_cma"]:
    d = mean(f"{name}_00000-04999.csv")
    if d is not None and name in timing and timing[name]["ms_per_step"] < 10:
      fast[name] = (d.total_cost.mean(), timing[name]["ms_per_step"])
  best = min(fast, key=lambda k: fast[k][0])
  L += ["", "## Learned residual on the steer output: skipped", "",
        "Rule: add a small learned residual only if a fast controller (ms/step well under the 100 ms control "
        f"period) scores below 48 on test. Best fast controller: `{best}` at {fast[best][0]:.2f} "
        f"({fast[best][1]:.2f} ms/step), {fast[best][0] - 48:.1f} points above 48, so no residual was trained. "
        "The only controllers below 48 are the two iLQR variants (40.59, and 40.23 risk-sensitive), which take "
        "64-72 ms of the 100 ms period and are not fast controllers in this sense."]
  (R / "tuning" / "MPC_CMA.md").write_text("\n".join(L) + "\n")
  print("\n".join(L))


if __name__ == "__main__":
  main()
